from PIL import Image, ImageDraw
im=Image.open('radiograph.jpg').convert('RGB'); W,H=im.size
d=ImageDraw.Draw(im)
for i in range(1,10):
    x=int(W*i/10); d.line([(x,0),(x,H)],fill=(255,0,0),width=3); d.text((x+3,5),str(i),fill=(255,0,0))
for j in range(1,6):
    y=int(H*j/6); d.line([(0,y),(W,y)],fill=(0,255,0),width=3); d.text((5,y+3),str(j),fill=(0,255,0))
im.save('grid.png'); print(im.size)
"", "description": "Overlay coordinate grid"}

{"command": "python3 -c "
from PIL import Image
im=Image.open('radiograph.jpg'); W,H=im.size
bands={'A':(0,int(W*0.34)),'B':(int(W*0.33),int(W*0.67)),'C':(int(W*0.66),W)}
for k,(a,c) in bands.items():
    s=im.crop((a,int(H*0.24),c,int(H*0.50)))
    s=s.resize((int(s.width*2.4),int(s.height*2.4)))
    s.save(f'maxA_{k}.png'); print(k,s.size)
"", "description": "Zoom maxillary root/apical band"}

